/**
 * HTTP 请求封装（沿用 CRMEB 风格的通用请求层）
 * ------------------------------------------------------------------
 * 说明：管理端当前的数据层是 utils/auth.js 的本地实现，这个 request.js 是
 * 为将来切换真实后端预留的通用请求器 —— 各业务模块切后端时直接换数据层实现，
 * 请求细节（域名前缀、加密响应解压、状态码分流）统一收在这里。
 *
 * 约定：
 *   - URL 前缀 /zx/datainf/ 是后端统一网关路径；
 *   - 响应若带 encode 标记，说明 body 被压缩过，需要 decompress 解压
 *     （JSON 解压失败则回退 URI 解码，两条路都试）；
 *   - 状态码 200 视为成功；410000/410001/410002/40000 为登录态相关业务码，
 *     501 为服务端显式拒绝，其余按 message 透传错误。
 *
 * 用法：request.get(url, data, { noAuth: true })
 *   noAuth   —— 预留：跳过登录校验（当前校验逻辑被注释，待接入 token 后启用）
 *   noVerify —— 透传完整响应（含 header），由调用方自行解析
 */
import {
    HTTP_REQUEST_URL,
    HEADER,
    TOKENNAME
} from '@/config/app';
import $ from 'jquery'
// 回话密钥名称 请勿修改此配置
// let TOKENNAME = 'X-Token';
function baseRequest(url, method, data, {
    noAuth = false,
    noVerify = false
}) {
    console.log(method)
    let Url = HTTP_REQUEST_URL,
        header = HEADER;
    // if (!noAuth) {
    //     //登录过期自动登录
    //     if (!store.state.app.token && !checkLogin()) {
    //         toLogin();
    //         return Promise.reject({
    //             msg: '未登录'
    //         });
    //     }
    // }
    return new Promise((reslove, reject) => {
        $.ajax({
            url: Url + '/mysql/' + url,
            type: method || 'GET',
            header: header,
            // processData: false,
            dataType: 'json',
            data: JSON.stringify(data) || {},
            success: (res) => {
                // console.log(data)
                // 压缩响应解压：优先按 JSON 解，失败再按 URL 编码解（后端两种编码都可能出现）
                if (res.data && res.data.encode) {
                    try {
                        res.data = JSON.parse(decompress(res.data.data));
                    } catch (e) {
                        res.data = decompress(decodeURI(res.data.data));
                    }
                }
                // noVerify 模式直接返回原始响应，由调用方判断
                if (noVerify)
                    reslove(res);
                else if (res.data.status == 200)
                    reslove(res.data, res);
                // 登录态相关业务码：原样 reject 业务数据，调用方通常在此统一跳登录
                else if ([410000, 410001, 410002, 40000].indexOf(res.data.status) !== -1) {
                    reject(res.data);
                } else if (res.data.status == 501) {
                    reject(res.data);
                } else {
                    reject(res.data.message || '系统错误')
                };
            },
            fail: (message) => {
                reject('请求失败');
            },
            error: (err) => {
                reslove({
                    code: '400',
                    msg: err
                });
            }
        })
    });
}
// 按 HTTP 动词批量生成快捷方法：request.get / request.post / ...
const request = {};
['options', 'get', 'post', 'put', 'head', 'delete', 'trace', 'connect'].forEach((method) => {
    request[method] = (api, data, opt) => baseRequest(api, method, data, opt || {})
});
export default request;
